let shuttingDown = false;

process.on('SIGTERM', async () => {
  shuttingDown = true;               // readiness probe now returns not-ready
  await sleep(3000);                 // give the load balancer time to notice
  server.close();                    // stop accepting new connections
  await drainInFlightRequests();     // let existing ones finish
  await db.end();
  await queueConsumer.stop();
  process.exit(0);
});

app.get('/health/ready', (req, res) => {
  res.status(shuttingDown ? 503 : 200).send();
});

